const fs=require('fs'),path=require('path'),{chromium}=require('playwright');
const args=process.argv.slice(2),arg=(n,f='')=>{const i=args.indexOf(n);return i>=0&&args[i+1]?args[i+1]:f};
const base=arg('--url','http://localhost/greenportal').replace(/\/$/,''),empresa=arg('--empresa','Modelo'),usuario=arg('--usuario','admin'),senha=arg('--senha', process.env.GREEN_TEST_PASSWORD || ''),cdp=arg('--cdp',''),out=path.resolve(arg('--saida','tests/resultado-exportacao-requisitos-legais-20260924.json'));
const result={startedAt:new Date().toISOString(),checks:[],status:'REPROVADO',temporary:{}};const check=(name,ok,details='')=>{result.checks.push({name,ok:!!ok,details});console.log(`${ok?'PASS':'FAIL'} - ${name}${details?`: ${details}`:''}`);if(!ok)throw new Error(name)};
async function main(){let browser;try{browser=cdp?await chromium.connectOverCDP(cdp):await chromium.launch({headless:true});const context=cdp?(browser.contexts()[0]||await browser.newContext()):await browser.newContext();const page=cdp?(context.pages()[0]||await context.newPage()):await context.newPage();page.on('dialog',d=>d.accept().catch(()=>{}));page.setDefaultTimeout(30000);
await page.goto(base+'/index.php',{waitUntil:'domcontentloaded'});await page.locator('#empresa').selectOption({label:empresa}).catch(()=>page.locator('#empresa').selectOption({value:empresa}));await page.locator('#userid').fill(usuario);await page.locator('#senha').fill(senha);await page.locator('form.login-form button[type="submit"]').click();await page.waitForURL(/\/principal\/main\.php/);check('Login realizado',true);await page.locator('[data-sidebar-toggle]').click().catch(()=>{});await page.locator('#menuSearch').fill('Requisitos legais');await page.locator('button[data-open-tab][data-tab-url*="modulolegal_requisitoslegais.php"]').click();const frame=page.frameLocator('iframe[src*="modulolegal_requisitoslegais.php"]');await frame.locator('#requisitosLegaisBatchGrid tbody tr').first().waitFor({state:'visible'});const cols=await frame.locator('#requisitosLegaisBatchGrid thead th:visible[data-column]').evaluateAll(xs=>xs.map(x=>x.dataset.column));const button=frame.locator('[data-export-requisitos]').first();check('Botão de exportação disponível',await button.count()===1);const responsePromise=page.waitForResponse(r=>r.request().method()==='POST'&&r.url().includes('modulolegal_requisitoslegais.php'),{timeout:30000});await button.click();const response=await responsePromise;check('Solicitação de exportação HTTP 200',response.status()===200,`HTTP ${response.status()}`);const body=await response.json().catch(()=>({}));check('Backend confirmou a solicitação',body.ok===true,JSON.stringify(body));await page.waitForTimeout(1200);const alerts=await page.evaluate(async()=>await(await fetch('/greenportal/principal/alertas.php?_='+Date.now(),{credentials:'same-origin'})).json());const alert=(alerts.alerts||[]).find(x=>String(x.link_status||'').includes('transacao=modulolegal_requisitoslegais'));check('Alerta de exportação criado',!!alert);const match=String(alert?.link_status||'').match(/codexportacaogrid=(\d+)/);check('Job identificado no alerta',!!match);const jobId=Number(match[1]);result.temporary.jobId=jobId;let status=null;for(let i=0;i<30;i++){status=await page.evaluate(async url=>await(await fetch(url,{credentials:'same-origin',cache:'no-store'})).json(),`${base}/principal/export_status.php?codexportacaogrid=${jobId}&transacao=modulolegal_requisitoslegais`);if(status.job?.status==='CONCLUIDA'||status.job?.status==='ERRO')break;await page.waitForTimeout(1000)}check('Job concluído',status.job?.status==='CONCLUIDA',JSON.stringify(status.job||status));const file=String(status.job?.arquivo||'');check('Arquivo XLSX informado',file.toLowerCase().endsWith('.xlsx'),file);const download=await page.request.get(file.startsWith('/')?base+file:file),bytes=await download.body();check('Download XLSX HTTP 200',download.status()===200,`HTTP ${download.status()}`);check('Arquivo XLSX possui assinatura ZIP',bytes[0]===0x50&&bytes[1]===0x4b,`${bytes.length} bytes`);result.temporary.file=file;result.columns=cols;result.status='APROVADO'}catch(error){result.error=error.message;throw error}finally{result.finishedAt=new Date().toISOString();fs.mkdirSync(path.dirname(out),{recursive:true});fs.writeFileSync(out,JSON.stringify(result,null,2));if(browser&&!cdp)await browser.close()}}main().catch(error=>{console.error(`ERRO FATAL: ${error.stack||error.message}`);process.exit(1)});
